<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_admin();require __DIR__.'/../../app/helpers/layout.php';render_start('Penjaga','Akun penjaga dan admin',$u);dashboard_nav('admin');render_mid('Penjaga','Admin disamarkan sebagai akun penjaga di login publik',$u);$rows=$pdo->query("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='penjaga' ORDER BY u.id DESC")->fetchAll();?><div class="card"><div class="toolbar"><b>Penjaga Perpustakaan</b><a href="/admin/staff/create.php" class="btn btn-primary">+ Tambah Penjaga</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Username</th><th>Nama</th><th>Email</th><th>Akses</th><th>Status</th><th>Login Terakhir</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=$r['is_admin']?'<span class="badge red">ADMIN</span>':'<span class="badge">PENJAGA</span>'?></td><td><span class="badge green"><?=e($r['status'])?></span></td><td><?=e($r['last_login_at']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div><?php render_end(); ?>
